-- 0032_dashboard_system_seed.sql seeded "vue-architecture-applicative"'s
-- three panels pointing at architecture-neo4j (Cypher). Following the
-- precedent of the prior backfills in this series, this migration points
-- the dashboard's latest revision (2) at the native Postgres datasource:
-- all three panels are fixed 1-hop patterns (Flow/Serving between
-- ApplicationComponent and BusinessActor, or a plain element count), so no
-- recursion is needed. "acteurs-servis" keeps the source's slightly odd but
-- faithfully reproduced $couche filter, which compares the served
-- element's ArchiMate layer (always "Business" for a BusinessActor) against
-- a dashboard parameter that also allows "Application" — a value that can
-- never match here, exactly as in the original Cypher.
UPDATE "dashboard_revisions" AS dr
SET "definition" = $def$
{"id": "vue-architecture-applicative", "title": "Vue d’ensemble applicative", "description": "Synthèse des composants applicatifs, de leur documentation et des acteurs métier servis.", "category": "Applications", "schemaVersion": 2, "parameters": [], "panels": [{"id": "composants-connectes", "panel": {"title": "Composants applicatifs connectés par des flux", "description": "Composants applicatifs atteints par un flux direct depuis un autre composant applicatif.", "resultType": "graph", "parameters": [], "visualization": {"type": "graph"}, "query": {"datasourceId": "postgres-app-db", "language": "sql", "text": "SELECT COALESCE(array_agg(node_id ORDER BY node_name ASC), ARRAY[]::text[]) AS \"nodeIds\"\nFROM (\n  SELECT DISTINCT target.uuid AS node_id, target.name AS node_name\n  FROM relationships r\n  JOIN workspaces rw ON rw.id = r.workspace_id\n  JOIN elements source_el ON source_el.uuid = r.source_uuid\n  JOIN workspaces sw ON sw.id = source_el.workspace_id\n  JOIN elements target ON target.uuid = r.target_uuid\n  JOIN workspaces tw ON tw.id = target.workspace_id\n  WHERE rw.organization_id = $organizationId\n    AND sw.organization_id = $organizationId\n    AND tw.organization_id = $organizationId\n    AND r.type = 'Flow'\n    AND source_el.type = 'ApplicationComponent'\n    AND target.type = 'ApplicationComponent'\n    AND target.name IS NOT NULL\n  ORDER BY target.name ASC\n  LIMIT 100\n) x"}}, "layout": {"x": 0, "y": 0, "width": 9, "height": 7}, "parameterBindings": {}}, {"id": "sans-documentation", "panel": {"title": "Composants applicatifs sans documentation", "description": "Nombre de composants applicatifs sans documentation renseignée.", "resultType": "metrics", "parameters": [], "visualization": {"type": "metric"}, "query": {"datasourceId": "postgres-app-db", "language": "sql", "text": "SELECT count(*)::integer AS count\nFROM (\n  SELECT e.uuid\n  FROM elements e\n  JOIN workspaces w ON w.id = e.workspace_id\n  WHERE w.organization_id = $organizationId\n    AND e.type = 'ApplicationComponent'\n    AND e.description IS NULL\n  LIMIT 500\n) capped"}}, "layout": {"x": 9, "y": 0, "width": 3, "height": 3}, "parameterBindings": {}}, {"id": "acteurs-servis", "panel": {"title": "Acteurs métier servis par les composants applicatifs", "description": "Liste chaque composant applicatif et les acteurs métier qu'il sert directement.", "resultType": "table", "parameters": [{"name": "couche", "label": "Couche ArchiMate", "type": "enum", "required": false, "defaultValue": "Business", "allowedValues": ["Application", "Business"]}], "visualization": {"type": "table"}, "query": {"datasourceId": "postgres-app-db", "language": "sql", "text": "SELECT COALESCE(jsonb_agg(jsonb_build_object('id', node_id, 'name', node_name, 'type', node_type) ORDER BY node_name ASC), '[]'::jsonb) AS rows\nFROM (\n  SELECT DISTINCT target.uuid AS node_id, target.name AS node_name, target.type AS node_type\n  FROM relationships r\n  JOIN workspaces rw ON rw.id = r.workspace_id\n  JOIN elements source_el ON source_el.uuid = r.source_uuid\n  JOIN workspaces sw ON sw.id = source_el.workspace_id\n  JOIN elements target ON target.uuid = r.target_uuid\n  JOIN workspaces tw ON tw.id = target.workspace_id\n  WHERE rw.organization_id = $organizationId\n    AND sw.organization_id = $organizationId\n    AND tw.organization_id = $organizationId\n    AND r.type = 'Serving'\n    AND source_el.type = 'ApplicationComponent'\n    AND target.type = 'BusinessActor'\n    AND target.name IS NOT NULL\n    AND (CASE\n    WHEN target.type LIKE 'Business%' OR target.type IN ('Contract', 'Representation', 'Product') THEN 'Business'\n    WHEN target.type LIKE 'Application%' OR target.type = 'DataObject' THEN 'Application'\n    WHEN target.type LIKE 'Technology%' OR target.type IN ('Node', 'Device', 'SystemSoftware', 'Path', 'CommunicationNetwork', 'Artifact') THEN 'Technology'\n    WHEN target.type IN ('Equipment', 'Facility', 'DistributionNetwork', 'Material') THEN 'Physical'\n    WHEN target.type IN ('Stakeholder', 'Driver', 'Assessment', 'Goal', 'Outcome', 'Principle', 'Requirement', 'Constraint', 'Meaning', 'Value') THEN 'Motivation'\n    WHEN target.type IN ('Resource', 'Capability', 'CourseOfAction', 'ValueStream') THEN 'Strategy'\n    WHEN target.type IN ('WorkPackage', 'Deliverable', 'ImplementationEvent', 'Plateau', 'Gap') THEN 'Implementation'\n    ELSE 'Composite'\n  END) = $couche\n  ORDER BY target.name ASC\n  LIMIT 500\n) x"}}, "layout": {"x": 0, "y": 7, "width": 12, "height": 5}, "parameterBindings": {"couche": {"source": "constant", "value": "Business"}}}], "createdAt": "2026-08-07T00:00:00.000Z", "updatedAt": "2026-08-17T03:00:00.000Z", "createdBy": "christophe.lacombe", "updatedBy": "system"}
$def$::jsonb
FROM "dashboards" AS dd
WHERE dr."dashboard_id" = dd."id"
  AND dd."dashboard_id" = 'vue-architecture-applicative'
  AND dd."workspace_id" IS NULL
  AND dr."revision" = dd."latest_revision";
